UPDATE t_seat_inventory SET sell_status = 2, reservation_id = #{reservationId}, order_number = #{orderNumber}, version = version + 1, edit_time = NOW() WHERE program_id = #{programId}
AND seat_id IN
#{seat.seatId}
AND (seat_id, ticket_category_id, price_in_cents) IN
(#{seat.seatId}, #{seat.ticketCategoryId}, #{seat.priceInCents})
AND sale_version = #{saleVersion} AND sell_status = 1 AND reservation_id IS NULL AND order_number IS NULL AND status = 1

UPDATE t_seat_inventory
SET sell_status = #{targetStatus},
    reservation_id = CASE WHEN #{targetStatus} = 1 THEN NULL ELSE reservation_id END,
    order_number = CASE WHEN #{targetStatus} = 1 THEN NULL ELSE order_number END,
    version = version + 1,
    edit_time = NOW()
WHERE program_id = #{programId}
  AND order_number = #{orderNumber}
  AND reservation_id = #{reservationId}
  AND sell_status = #{sourceStatus}
  AND status = 1

mapper.select:
SELECT COUNT(*)
FROM t_seat_inventory
WHERE program_id = #{programId}
  AND ticket_category_id = #{ticketCategoryId}
  AND sell_status = 1
  AND status = 1

SELECT COUNT(*)
FROM t_seat_inventory
WHERE program_id = #{programId}
  AND sale_version != #{saleVersion}
  AND status = 1
